        const floatX *b = inp2 + row * static_cast<size_t>(C);
        float part = 0.0f;
        for (int c = static_cast<int>(lid); c < C; c += static_cast<int>(lsize)) {
          float o = a[c] + b[c];
          res[c] = o;
          s_r[c] = o;
          part += o;
        }
        float sum = sycl::reduce_over_group(g, part, sycl::plus<float>{});
        float m = sum / static_cast<float>(C);
