        float vpart = 0.0f;
        for (int c = static_cast<int>(lid); c < C; c += static_cast<int>(lsize)) {
          float d = s_r[c] - m;
          vpart += d * d;
        }
        float vsum = sycl::reduce_over_group(g, vpart, sycl::plus<float>{});
        float v = vsum / static_cast<float>(C);
        float s = sycl::rsqrt(v + eps);
