    for (int c = static_cast<int>(lid); c < C; c += static_cast<int>(lsize)) {
      float n = s * (res[c] - m);
      out[c] = n * weight[c] + bias[c];
    }
    if (lid == 0) {
      mean[row] = m;
      rstd[row] = s;
    }
  }).wait();
}

